entries[63479] = { ["name"] = "Kettenblitz", ["text"] = "500 Mana Unbegrenzte Reichweite\nWirken in 2 sek.\nTrifft einen Feind mit einem Blitzschlag, der auf einen in der Nähe befindlichen Feind überspringt. Der Zauber wirkt sich auf bis zu 5 Ziele aus und verursacht bei jedem Naturschaden." }
entries[63480] = { ["name"] = "Überladen", ["text"] = "Sofort\nFokussiert die gesamte Energie des Zaubernden in eine einzige Blitzkugel. Die Kugel wächst 6 sec lang an, bis sie letztendlich explodiert, an allen Feinden innerhalb von 20 Metern 25000 Naturschaden verursacht und sie zu Boden stößt." }
entries[63481] = { ["name"] = "Überladen", ["text"] = "Kanalisiert (Wirken in 6 sek.) 7 sek. Abklingzeit\nFokussiert die gesamte Energie des Zaubernden in eine einzige Blitzkugel. Die Kugel wächst 6 sec lang an, bis sie letztendlich explodiert, an allen Feinden innerhalb von 20 Metern 25000 Naturschaden verursacht und sie zu Boden stößt." }
